CREATE TABLE IF NOT EXISTS hub_linkedin_pages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL REFERENCES social_connections(id),organization_urn TEXT NOT NULL,name TEXT NOT NULL,brand_id TEXT REFERENCES hub_brands(id),enabled INTEGER NOT NULL DEFAULT 0,discovered_at INTEGER NOT NULL,UNIQUE(workspace_id,organization_urn));
CREATE TABLE IF NOT EXISTS hub_media(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),object_key TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hub_posts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),page_id TEXT REFERENCES hub_linkedin_pages(id),created_by TEXT NOT NULL,text TEXT NOT NULL,media_id TEXT REFERENCES hub_media(id),alt_text TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('draft','scheduled','processing','published','failed','uncertain','cancelled')),scheduled_at INTEGER,time_zone TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,client_key TEXT NOT NULL,payload_hash TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER,lease_id TEXT,lease_until INTEGER,stage TEXT,error_code TEXT,error_message TEXT,provider_post_id TEXT,provider_image_id TEXT,published_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,client_key));
CREATE INDEX IF NOT EXISTS hub_posts_due ON hub_posts(status,next_attempt_at,scheduled_at);
CREATE TABLE IF NOT EXISTS hub_post_events(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES hub_posts(id),status TEXT NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hub_post_metrics(post_id TEXT PRIMARY KEY REFERENCES hub_posts(id),impressions INTEGER,unique_impressions INTEGER,clicks INTEGER,likes INTEGER,comments INTEGER,shares INTEGER,synced_at INTEGER,checked_at INTEGER,error_message TEXT);
CREATE TABLE IF NOT EXISTS hub_scheduler(id TEXT PRIMARY KEY,heartbeat_at INTEGER NOT NULL);
